BEGIN
 FOR r IN SELECT value FROM jsonb_array_elements(cases)LOOP
  IF (r->>'case')::integer IN(3,5,7)THEN w:=array_fill(0::numeric,ARRAY[1326]);FOR item IN SELECT value FROM jsonb_array_elements(r->'sparse')LOOP w[(item->>'combo')::integer+1]:=(item->>'weight')::numeric;END LOOP;
  ELSE SELECT array_agg(CASE (r->>'case')::integer WHEN 2 THEN (j%5+1)::numeric WHEN 4 THEN 1000000000000::numeric-j%17 WHEN 8 THEN 1000000000000::numeric-(j*7)%19 ELSE 1::numeric END ORDER BY j)INTO w FROM generate_series(0,1325)j;END IF;
