  mass:=ARRAY[row.current_w,row.current_t,row.current_z-row.current_w-row.current_t,row.current_z,row.terminal_w,row.terminal_t,row.terminal_z-row.terminal_w-row.terminal_t,row.terminal_z];
  FOR i IN 0..3 LOOP IF mass[i+1]<>(r#>>ARRAY['current',i::text])::numeric OR mass[i+5]<>(r#>>ARRAY['terminal',i::text])::numeric THEN RAISE EXCEPTION 'independent exact public WTL golden mismatch case% slot%',r->>'case',i;END IF;END LOOP;
  bits:=public.fn_gto_v31_public215_bits(public.fn_gto_v31_public215_features((r->>'combo')::integer,r->>'board_text',template,mass));IF bits IS DISTINCT FROM r->'features_be'THEN RAISE EXCEPTION 'full215 independent binary64 golden mismatch case%',r->>'case';END IF;count_cases:=count_cases+1;
 END LOOP;
 IF count_cases<>8 THEN RAISE EXCEPTION 'incomplete independent public parity census';END IF;
 RAISE NOTICE 'PUBLIC215_INDEPENDENT_SQL_8_PUBLIC_EXACT_WTL_FULL215_BYTE_PARITY_PASS';
